parameters.jsCode:
const agentRawOutput = $input.first().json.output;

function extractJson(text) {
  // 1. Direct parse (clean JSON output)
  try { return JSON.parse(text); } catch (_) {}

  // 2. Markdown code block: ```json ... ``` or ``` ... ```
  const cbMatch = text.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
  if (cbMatch) {
    try { return JSON.parse(cbMatch[1].trim()); } catch (_) {}
  }

  // 3. Last-resort: find outermost { ... } object
  const start = text.indexOf('{');
  const end   = text.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try { return JSON.parse(text.slice(start, end + 1)); } catch (_) {}
  }

  return null;
}

const agentData = extractJson(agentRawOutput);
if (!agentData || !agentData.vorschlag) {
  throw new Error('Agent-Output ungueltig oder kein vorschlag-Feld: ' + String(agentRawOutput).slice(0, 200));
}

const state      = $('Edit Fields2').first().json.state;
const anfrage    = state.anfrage;
const pauschale  = $('Budgetberechnung').first().json.pauschale || 200;
const guestCount = anfrage.personenanzahl;
const budget     = anfrage.budget;

let sumPreisPP = 0;
const vorschlag = agentData.vorschlag.map(function(item) {
  sumPreisPP += item.preisPerson;
  return {
    menuItemId:  item.menuItemId,
    name:        item.name,
    category:    item.category,
    anzahl:      guestCount,
    preisPerson: Math.round(item.preisPerson * 100) / 100,
    gesamtpreis: Math.round(item.preisPerson * guestCount * 100) / 100,
    begruendung: item.begruendung || ''
  };
});

const menuGesamtpreis  = Math.round(sumPreisPP * guestCount * 100) / 100;
const gesamtpreis      = Math.round((menuGesamtpreis + pauschale) * 100) / 100;
const budgetEingehalten = gesamtpreis <= budget;

const proposal = {
  vorschlag, personenanzahl: guestCount, menuGesamtpreis,
  verwaltungspauschale: pauschale, gesamtpreis, budget,
  budgetEingehalten, begruendung: agentData.begruendung || ''
};

const lines = [
  '=== MENUE-VORSCHLAG ===',
  'Kunde: '  + state.kunde.telegram_name,
  'Anlass: ' + anfrage.anlass + ' | ' + anfrage.datum_text + ' | ' + anfrage.ort,
  'Personen: ' + guestCount + ' | Budget: EUR ' + budget,
  '',
  'AUSGEWAEHLTE GERICHTE:'
].concat(vorschlag.map(function(i) {
  return '  - ' + i.name + ' (' + i.category + ') EUR ' + i.preisPerson +
         '/Pers. x ' + guestCount + ' = EUR ' + i.gesamtpreis;
})).concat([
  '',
  'Menupreise gesamt:    EUR ' + menuGesamtpreis,
  'Verwaltungspauschale: EUR ' + pauschale,
  'GESAMTPREIS:          EUR ' + gesamtpreis,
  'Budget:               EUR ' + budget,
  'Budget eingehalten:   ' + (budgetEingehalten ? 'JA' : 'NEIN - Ueberschreitung!'),
  '',
  'BEGRUENDUNG: ' + (proposal.begruendung || '(keine)'),
  '',
  '--- JSON (fuer Backend-Integration) ---',
  JSON.stringify(proposal, null, 2)
]);

return [{ json: Object.assign({}, proposal, { emailBody: lines.join('\n'), state }) }];

